-- Deep Cuts EDH community beta. Apply to the existing D1 before site release.
CREATE TABLE IF NOT EXISTS community_profiles(id TEXT PRIMARY KEY,handle TEXT NOT NULL UNIQUE COLLATE NOCASE,key_hash TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',avatar TEXT NOT NULL DEFAULT 'Chainer, Dementia Master',created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS community_limits(subject TEXT NOT NULL,date_key TEXT NOT NULL,action TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(subject,date_key,action));
CREATE TABLE IF NOT EXISTS community_comments(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,topic TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'discussion' CHECK(kind IN ('discussion','doctor')),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'visible' CHECK(status IN ('visible','hidden')),created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS community_comments_topic ON community_comments(topic,status,created_at DESC);
CREATE TABLE IF NOT EXISTS community_follows(follower_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,target_type TEXT NOT NULL CHECK(target_type IN ('profile','commander')),target TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(follower_id,target_type,target));
CREATE TABLE IF NOT EXISTS community_decks(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,title TEXT NOT NULL,commander TEXT NOT NULL,content TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS community_decks_owner ON community_decks(owner_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS community_deck_versions(deck_id TEXT NOT NULL REFERENCES community_decks(id) ON DELETE CASCADE,version INTEGER NOT NULL,content TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(deck_id,version));
CREATE TABLE IF NOT EXISTS community_playtests(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,deck_id TEXT REFERENCES community_decks(id) ON DELETE SET NULL,commander TEXT NOT NULL,opponent TEXT NOT NULL,result TEXT NOT NULL CHECK(result IN ('win','loss','draw')),turns INTEGER NOT NULL CHECK(turns BETWEEN 1 AND 60),note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS community_test_commander ON community_playtests(commander,created_at DESC);
CREATE TABLE IF NOT EXISTS community_challenges(id TEXT PRIMARY KEY,title TEXT NOT NULL,commander TEXT NOT NULL,opens_at TEXT NOT NULL,closes_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS community_entries(challenge_id TEXT NOT NULL REFERENCES community_challenges(id) ON DELETE CASCADE,deck_id TEXT NOT NULL REFERENCES community_decks(id) ON DELETE CASCADE,member_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(challenge_id,member_id));
CREATE UNIQUE INDEX IF NOT EXISTS community_entries_deck ON community_entries(challenge_id,deck_id);
CREATE TABLE IF NOT EXISTS community_votes(challenge_id TEXT NOT NULL,voter_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,deck_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(challenge_id,voter_id),FOREIGN KEY(challenge_id,deck_id) REFERENCES community_entries(challenge_id,deck_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS community_reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,comment_id TEXT NOT NULL REFERENCES community_comments(id) ON DELETE CASCADE,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT (datetime('now')),UNIQUE(reporter_id,comment_id));
CREATE INDEX IF NOT EXISTS community_reports_pending ON community_reports(status,created_at);
CREATE TABLE IF NOT EXISTS community_reactions(comment_id TEXT NOT NULL REFERENCES community_comments(id) ON DELETE CASCADE,member_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,PRIMARY KEY(comment_id,member_id));
